class Color:
    def __init__(self, r, g, b):
        self.r = r
        self.g = g
        self.b = b

    def __str__(self):
        return f"rgb({self.r}, {self.g}, {self.b})"

    def __repr__(self):
        return f"Color({self.r}, {self.g}, {self.b})"

    def hex(self):
        return f"#{self.r:02x}{self.g:02x}{self.b:02x}"
